css:
.po-print {
  font-size: 11px;
  font-family: Arial, sans-serif;
}

.header h2 {
  text-align: left;
  font-weight: bold;
}

.contact-info {
  width: 100%;
  margin: 15px 0;
}

.contact-info td {
  vertical-align: top;
  padding: 4px;
  font-size: 11px;
}

.items {
  width: 100%;
  border-collapse: collapse;
  margin-top: 20px;
}

.items th,
.items td {
  border: 1px solid #ccc;
  padding: 6px 4px;
  text-align: left;
}

.items th {
  background-color: #f0f0f0;
}

.items td:nth-child(3),
.items td:nth-child(4),
.items td:nth-child(5),
.items td:nth-child(6),
.items td:nth-child(7),
.items td:nth-child(8) {
  text-align: right;
}

.totals {
  margin-top: 20px;
  float: right;
  width: 300px;
}

.totals td {
  padding: 4px;
  font-size: 11px;
}

.totals td:first-child {
  text-align: right;
}

.footer {
  clear: both;
  margin-top: 50px;
  font-size: 11px;
}

html:
 {% if letter_head and not no_letterhead -%}
    {% if print_settings.repeat_header_footer %}
        <div id="header-html" class="hidden-pdf" style="border-bottom: 1px solid black;">
            <div class="letter-head">
                {{ letter_head }}
            </div>
        </div>
    {%- endif %}
{%- endif %}

{% if(doc.supplier) %}
    {% set supplier = frappe.get_doc('Supplier', doc.supplier ) %}
{% endif %}

{% if(doc.supplier_address) %}
    {% set supplier_address_doc = frappe.get_doc('Address', doc.supplier_address ) %}
{% endif %}

  <hr>
{% if(doc.supplier) %}
    {% set supplier = frappe.get_doc('Supplier', doc.supplier ) %}
{% endif %}
  <table class="contact-info">
    <tr>
      <td>
        <strong>Contact</strong><br>
       
      </td>
      <td style="text-align: right;">
        <strong>Status:</strong> {{ doc.status }}<br>
        
       
      </td>
    </tr>
    <tr>
        <td> {{ supplier.supplier_name }}</td>
        <td style="text-align: right;"> <strong>PO No:</strong> {{ doc.name }}</td>
    </tr>
    <tr>
        <td> {% if supplier.tax_id %}Tax Number {{ supplier.tax_id }}{% endif %}</td>
        <td style="text-align: right;"> <strong>PO Date:</strong> {{ frappe.utils.formatdate(doc.transaction_date) }}</td>
    </tr>
    <tr>
        <td></td>
        <td style="text-align: right;"> <strong>Due On:</strong> {{ frappe.utils.formatdate(doc.schedule_date) }}</td>
    </tr>
  </table>

  <table>
    <thead>
      <tr>
        <th>#</th>
        <th>Product</th>
        <th>Qty</th>
        <th>Unit Price</th>
        <!--<th>Dis.</th>-->
        <th>Total Before VAT</th>
        <th>VAT</th>
        <th>VAT Amount</th>
        <th>Total</th>
      </tr>
    </thead>
    <tbody>
        {% set total = namespace(amount = 0) %}
        {% for item_row in doc.items %}
            {% set total.amount = item_row.amount %}
            <tr>
                <td>{{ loop.index }}</td>
                <td>
                  <strong>{{ item_row.item_name }}</strong><br>
                  {{ item_row.description }}
                </td>
                <td>
                  {{ item_row.qty }}<br>
                  {{ item_row.uom }}
                </td>
                <td>{{ frappe.format_value(frappe.utils.flt(item_row.rate), currency=doc.currency) }}  </td>
                <!--<td>{{ item_row.discount_amount or 0.00 }}</td>-->
                <td>{{ frappe.format_value(frappe.utils.flt(item_row.amount), currency=doc.currency) }}</td>
                <td>
                {% if doc.taxes %}
                    {{ frappe.format(doc.taxes[0].rate, {'fieldtype': 'Percent'}) }}
                {% else %}
                    NA
                {% endif %}
                </td>

                <td>
                    {% if doc.taxes %}
                        {{ frappe.format_value(
                            (item_row.amount or 0) * (doc.taxes[0].rate or 0) / 100,
                            currency=doc.currency
                        ) }}
                    {% else %}
                        {{ frappe.format_value(0, currency=doc.currency) }}
                    {% endif %}
                </td>
                
                <td>
                    {% if doc.taxes %}
                        {{ frappe.format_value(
                            (item_row.amount or 0) +
                            ((item_row.amount or 0) * (doc.taxes[0].rate or 0) / 100),
                            currency=doc.currency
                        ) }}
                    {% else %}
                        {{ frappe.format_value(item_row.amount, currency=doc.currency) }}
                    {% endif %}
                </td>
            </tr>
        {% endfor %}
    </tbody>
  </table>

  <table class="totals">
    <tr>
      <td><strong>Total Before VAT:</strong></td>
      <td>{{ doc.get_formatted("net_total") }}</td>
    </tr>
    <tr>
      <td><strong>Total VAT:</strong></td>
      <td>{{ doc.get_formatted("total_taxes_and_charges") }}</td>
    </tr>
    <tr>
      <td><strong>Total:</strong></td>
      <td>{{ doc.get_formatted("grand_total") }}</td>
    </tr>
  </table>

  <div class="footer">
    <p>
      {% if doc.terms %}
        {{ doc.terms | replace('\n', '<br>') }}
      {% else %}
         
      {% endif %}
    </p>
    
  </div>
